export type Seg = { text: string; tone: Tone | undefined }
// The band line: the lead, then one part for each member of the counts field that has rows. A world with an error: that error.
// An empty list gives no part: the band yields.
const MEMBERS: readonly State[] = ['waiting', 'working', 'failed', 'done']
export const BAND = { idle: 'show', counts: 'state' } as const
export function bandSegs(w: World): readonly Seg[] {
  const tally: Seg[] = MEMBERS.map(m => ({ n: w.rows.filter(r => r.state === m).length, m })).filter(x => x.n > 0).map(x => ({ text: `${x.n} ${x.m}`, tone: TONES[x.m] }))
  return w.error ? [{ text: w.error, tone: 'err' }] : tally
}
